div.script:
document.addEventListener('DOMContentLoaded', function () {
    const table = document.getElementById('participation_budget_table');
    if (!table) {
        return;
    }
    const formatter = new Intl.NumberFormat('en-US', {
        minimumFractionDigits: 2,
        maximumFractionDigits: 2,
    });
    const totalDisplay = document.getElementById('participation_budget_total_display');
    const hiddenTotal = document.getElementById('participation_estimated_budget');
    const recalculateBudget = function () {
        let grandTotal = 0;
        table.querySelectorAll('tbody tr[data-budget-key]').forEach(function (row) {
            const quantity = parseFloat(row.querySelector('[data-budget-quantity]').value || '0') || 0;
            const unitAmount = parseFloat(row.querySelector('[data-budget-unit-amount]').value || '0') || 0;
            const lineTotal = quantity * unitAmount;
            grandTotal += lineTotal;
            row.querySelector('[data-budget-line-total]').textContent = formatter.format(lineTotal);
        });
        totalDisplay.textContent = formatter.format(grandTotal);
        hiddenTotal.value = grandTotal.toFixed(2);
    };
    table.addEventListener('input', recalculateBudget);
    recalculateBudget();
});
